import XCTest

/// Regression coverage for the hover-preview feature (plan: ~/.claude/plans/ethereal-inventing-wolf.md)
/// stealing keyboard focus from the real active tab — found via real-mouse QA, not by any automated
/// test: hovering a backgrounded tab's chip silently made it the first responder (a stale
/// `GhosttySurfaceView.wantsFocus` left over from when it was last actually active triggered
/// `viewDidMoveToWindow`'s auto-claim once the hover-preview re-homed it into a real window).
///
/// The surface itself is Metal-rendered and exposes nothing queryable for "who currently holds first
/// responder" (the same CMT-3 gap `GhosttyActionDispatchUITests` documents), so this proves the
/// regression the way a real user would notice it: type into the real active tab, hover a DIFFERENT
/// tab's chip, then type again and confirm the keystrokes still land in the originally-focused tab —
/// exercised through the shell's own OSC 0/2 retitling (issue #2), the same detector
/// `GhosttyActionDispatchUITests.testRunningCommandRetitlesTheTabChip` already uses.
///
/// Run with `make app-uitest` on a real GUI login session (XCUITest can't drive a headless run).
final class TerminalHoverPreviewUITests: XCTestCase {
  override func setUp() {
    super.setUp()
    continueAfterFailure = false
  }

  private func launchedApp() -> XCUIApplication {
    let app = XCUIApplication()
    app.launchArguments += ["-WorkroomUITestFixture", "1"]
    app.launchArguments += ["-WorkroomUITestNoRunCommand", "1"]
    app.launchArguments += ["-WorkroomUITestTerminalTabs", "2"]
    app.launchArguments += ["-ApplePersistenceIgnoreState", "YES"]
    app.launch()
    XCTAssertTrue(app.wait(for: .runningForeground, timeout: 15))
    return app
  }

  /// Every terminal tab chip, in strip order. Queried by PREFIX (the title isn't stable — shell
  /// integration retitles per command, issue #2), matching `GhosttyActionDispatchUITests`' pattern.
  private func tabChips(_ app: XCUIApplication) -> [XCUIElement] {
    let query = app.descendants(matching: .any)
      .matching(NSPredicate(format: "identifier BEGINSWITH %@", "terminal.tab."))
    return (0..<query.count).map { query.element(boundBy: $0) }
  }

  private func focusFirstTab(_ app: XCUIApplication) {
    app.activate()
    let chips = tabChips(app)
    XCTAssertGreaterThanOrEqual(chips.count, 2, "the fixture must seed 2 terminal tabs")
    XCTAssertTrue(chips[0].waitForExistence(timeout: 20))
    chips[0].click()
    // The click lands before the surface is first responder; without a beat the first keystrokes are
    // dropped (same note as GhosttyActionDispatchUITests.focusTerminal).
    RunLoop.current.run(until: Date().addingTimeInterval(1))
  }

  private func run(_ app: XCUIApplication, _ line: String) {
    app.typeText(line + "\r")
  }

  private func retitled(_ app: XCUIApplication, prefix: String) -> XCUIElement {
    app.descendants(matching: .any)
      .matching(NSPredicate(format: "identifier BEGINSWITH %@", "terminal.tab.\(prefix)"))
      .firstMatch
  }

  /// The regression test: hovering tab 2 while tab 1 is focused must not move keyboard focus.
  func testHoveringABackgroundTabDoesNotStealFocusFromTheActiveTab() {
    let app = launchedApp()
    focusFirstTab(app)

    let chips = tabChips(app)
    XCTAssertEqual(chips.count, 2)

    // Confirm keystrokes land in tab 1 BEFORE hovering, establishing the baseline.
    run(app, "echo before_hover_marker")
    let beforeMarker = retitled(app, prefix: "echo before_hover")
    XCTAssertTrue(
      beforeMarker.waitForExistence(timeout: 20), "tab 1 must retitle from its own running command")

    // Hover tab 2's chip long enough to pass the hover-preview's dwell (0.4s) and settle (0.05s).
    chips[1].hover()
    RunLoop.current.run(until: Date().addingTimeInterval(1.0))

    // Type again — if hovering had stolen first responder, this would land in tab 2 instead.
    run(app, "echo after_hover_marker")
    let afterMarker = retitled(app, prefix: "echo after_hover")
    XCTAssertTrue(
      afterMarker.waitForExistence(timeout: 20),
      "tab 1 must still be the one receiving keystrokes after hovering a different tab's chip — " +
        "if this fails, hovering silently stole first responder (the regression this test exists for)")

    // And tab 2 (the hovered one) must NOT have received the command instead.
    let tab2WronglyRetitled = app.descendants(matching: .any)
      .matching(NSPredicate(format: "identifier BEGINSWITH %@", "terminal.tab.echo after_hover"))
      .element(boundBy: 1)
    XCTAssertFalse(
      tab2WronglyRetitled.exists,
      "only one tab should show the after-hover command's title — a second match means it landed in " +
        "the hovered tab instead of the focused one")
  }

  /// Hovering a tab whose surface was never mounted must never spawn a shell — the hover-preview
  /// gates on `hasSurface`/`isPreviewEligible` before doing anything (Codex #3's spawn-guard concern).
  /// The fixture's 2 tabs both spawn on launch, so this instead confirms hovering the ALREADY-VISIBLE
  /// tab (which v1 explicitly shows no preview for) is a safe no-op — the closest this app's fixture
  /// seam gets to "a tab with nothing to preview" without adding new fixture surface.
  func testHoveringTheAlreadyVisibleTabIsANoOp() {
    let app = launchedApp()
    focusFirstTab(app)
    let chips = tabChips(app)

    chips[0].hover()  // tab 1 is already focused/visible — v1 shows no preview for it
    RunLoop.current.run(until: Date().addingTimeInterval(1.0))

    run(app, "echo still_focused_marker")
    let marker = retitled(app, prefix: "echo still_focused")
    XCTAssertTrue(
      marker.waitForExistence(timeout: 20), "hovering the already-active tab must not disturb focus")
  }
}

